'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { parse, CsvError } = require('../src/csv');

function assertCsvError(fn, line, column, pattern) {
  assert.throws(fn, (err) => {
    assert.ok(err instanceof CsvError, `expected CsvError, got ${err && err.name}`);
    assert.ok(err instanceof Error);
    assert.equal(err.line, line, 'line');
    assert.equal(err.column, column, 'column');
    if (pattern) assert.match(err.message, pattern);
    return true;
  });
}

test('parses simple records', () => {
  assert.deepEqual(parse('a,b,c\n1,2,3'), [
    ['a', 'b', 'c'],
    ['1', '2', '3'],
  ]);
});

test('empty string returns no records', () => {
  assert.deepEqual(parse(''), []);
  assert.deepEqual(parse('', { header: true }), []);
  assert.deepEqual(parse('', { skipEmptyLines: true }), []);
});

test('text must be a string', () => {
  for (const value of [undefined, null, 1, true, {}, [], Buffer.from('a'), new String('a')]) {
    assert.throws(() => parse(value), TypeError);
  }
});

test('custom delimiter', () => {
  assert.deepEqual(parse('a;b,c\n1;2', { delimiter: ';' }), [
    ['a', 'b,c'],
    ['1', '2'],
  ]);
  assert.deepEqual(parse('a\tb', { delimiter: '\t' }), [['a', 'b']]);
  assert.deepEqual(parse('"a b" c', { delimiter: ' ' }), [['a b', 'c']]);
});

test('invalid delimiters throw TypeError', () => {
  for (const delimiter of ['', ',,', '"', '\r', '\n', 1, null, {}]) {
    assert.throws(() => parse('a', { delimiter }), TypeError, `delimiter ${JSON.stringify(delimiter)}`);
  }
});

test('records may be separated by CRLF, LF or CR, mixed', () => {
  assert.deepEqual(parse('a\r\nb\nc\rd'), [['a'], ['b'], ['c'], ['d']]);
  assert.deepEqual(parse('a\n\rb'), [['a'], [''], ['b']]);
  assert.deepEqual(parse('a\r\r\nb'), [['a'], [''], ['b']]);
});

test('leading byte order mark is ignored', () => {
  assert.deepEqual(parse('﻿a,b'), [['a', 'b']]);
  assert.deepEqual(parse('﻿"a",b'), [['a', 'b']]);
  assert.deepEqual(parse('﻿'), []);
  // Only a leading one.
  assert.deepEqual(parse('a,﻿b\n﻿c'), [['a', '﻿b'], ['﻿c']]);
  assert.deepEqual(parse('﻿﻿a'), [['﻿a']]);
});

test('quoted fields keep delimiters and line breaks literally', () => {
  assert.deepEqual(parse('"a,b","c\nd","e\r\nf","g\rh"'), [['a,b', 'c\nd', 'e\r\nf', 'g\rh']]);
});

test('doubled quotes inside quoted fields are one quote', () => {
  assert.deepEqual(parse('"a""b","""","""x"""'), [['a"b', '"', '"x"']]);
  assert.deepEqual(parse('""'), [['']]);
  assert.deepEqual(parse('"",""'), [['', '']]);
});

test('a quote inside an unquoted field is an ordinary character', () => {
  assert.deepEqual(parse('a"b,c""d,e"\n'), [['a"b', 'c""d', 'e"']]);
  assert.deepEqual(parse(' "a"'), [[' "a"']]);
});

test('whitespace is never trimmed', () => {
  assert.deepEqual(parse(' a , b \n\t,  '), [
    [' a ', ' b '],
    ['\t', '  '],
  ]);
  assert.deepEqual(parse(' '), [[' ']]);
});

test('empty fields', () => {
  assert.deepEqual(parse(',\n,,'), [
    ['', ''],
    ['', '', ''],
  ]);
  assert.deepEqual(parse('a,'), [['a', '']]);
});

test('one trailing line break does not start a record', () => {
  assert.deepEqual(parse('a\n'), [['a']]);
  assert.deepEqual(parse('a\r\n'), [['a']]);
  assert.deepEqual(parse('a\r'), [['a']]);
  assert.deepEqual(parse('"a"\n'), [['a']]);
  assert.deepEqual(parse('a,\n'), [['a', '']]);
});

test('other empty lines are records with one empty field', () => {
  assert.deepEqual(parse('\n'), [['']]);
  assert.deepEqual(parse('\r\n'), [['']]);
  assert.deepEqual(parse('\n\n'), [[''], ['']]);
  assert.deepEqual(parse('a\n\n'), [['a'], ['']]);
  assert.deepEqual(parse('\na\n\nb\r\n\r\n'), [[''], ['a'], [''], ['b'], ['']]);
});

test('skipEmptyLines skips empty lines', () => {
  const opts = { skipEmptyLines: true };
  assert.deepEqual(parse('\n', opts), []);
  assert.deepEqual(parse('\na\n\n\r\nb\r\r\n', opts), [['a'], ['b']]);
  // A quoted empty field or whitespace is not an empty line.
  assert.deepEqual(parse('""\n \n', opts), [[''], [' ']]);
  assert.deepEqual(parse('"\n\n"', opts), [['\n\n']]);
});

test('header mode returns objects', () => {
  assert.deepEqual(parse('name,age\nAda,36\r\nAlan,41\n', { header: true }), [
    { name: 'Ada', age: '36' },
    { name: 'Alan', age: '41' },
  ]);
});

test('header only input returns no records', () => {
  assert.deepEqual(parse('a,b', { header: true }), []);
  assert.deepEqual(parse('a,b\n', { header: true }), []);
});

test('header mode with empty lines', () => {
  assert.deepEqual(parse('a\n\nx\n', { header: true }), [{ a: '' }, { a: 'x' }]);
  assert.deepEqual(parse('\n\na,b\n\n1,2\n\n', { header: true, skipEmptyLines: true }), [{ a: '1', b: '2' }]);
  assertCsvError(() => parse('a,b\n1,2\n\n', { header: true }), 3, 1, /Expected 2 fields/);
});

test('header names that collide with Object.prototype are own properties', () => {
  const [row] = parse('__proto__,constructor,toString\n1,2,3', { header: true });
  assert.deepEqual(Object.keys(row), ['__proto__', 'constructor', 'toString']);
  assert.equal(Object.getPrototypeOf(row), Object.prototype);
  assert.equal(Object.getOwnPropertyDescriptor(row, '__proto__').value, '1');
  assert.equal(row.constructor, '2');
});

test('duplicate header names are an error at the second occurrence', () => {
  assertCsvError(() => parse('a,b,a\n1,2,3', { header: true }), 1, 5, /Duplicate/);
  assertCsvError(() => parse('\n\nx,"y",\r\n"y"', { header: true, skipEmptyLines: true }), 3, 3, /Duplicate/);
  assertCsvError(() => parse('"a\nb",c,"a\nb"', { header: true }), 2, 5, /Duplicate/);
  assertCsvError(() => parse(',', { header: true }), 1, 2, /Duplicate/);
  // Not an error without header mode.
  assert.deepEqual(parse('a,a'), [['a', 'a']]);
});

test('wrong number of fields in header mode', () => {
  assertCsvError(() => parse('a,b\n1,2\n1,2,3\n', { header: true }), 3, 1, /Expected 2 fields but found 3/);
  assertCsvError(() => parse('a,b\n1', { header: true }), 2, 1, /Expected 2 fields but found 1/);
  // The line is the line where the record starts.
  assertCsvError(() => parse('a,b\n"x\ny\nz"', { header: true }), 2, 1);
  // Records of different lengths are fine without header mode.
  assert.deepEqual(parse('a,b\n1'), [['a', 'b'], ['1']]);
});

test('unclosed quoted field reports the opening quote', () => {
  assertCsvError(() => parse('"abc'), 1, 1, /Unclosed/);
  assertCsvError(() => parse('a,b\nc,"d\ne,f'), 2, 3, /Unclosed/);
  assertCsvError(() => parse('a,"b""'), 1, 3, /Unclosed/);
  assertCsvError(() => parse('"'), 1, 1, /Unclosed/);
});

test('character after a closing quote is an error at that character', () => {
  assertCsvError(() => parse('"a"b'), 1, 4, /Unexpected character/);
  assertCsvError(() => parse('x\r\ny,"a" '), 2, 5, /Unexpected character/);
  assertCsvError(() => parse('"a\r\nb"c'), 2, 3);
  assertCsvError(() => parse('"a\rb"c'), 2, 3);
  assertCsvError(() => parse('"a\n\nb"c'), 3, 3);
});

test('columns are counted in UTF-16 code units and ignore the BOM', () => {
  assertCsvError(() => parse('😀,"a"x'), 1, 6);
  assertCsvError(() => parse('﻿"a"x'), 1, 4);
  assertCsvError(() => parse('﻿\n"a'), 2, 1);
  assertCsvError(() => parse('é,"'), 1, 3);
});

test('the first error found reading left to right is thrown', () => {
  // Field count is checked at the end of record 2, before the unclosed quote on line 3.
  assertCsvError(() => parse('a,b\n1\n"x', { header: true }), 2, 1, /Expected/);
  // A bad character inside a record is found before that record ends.
  assertCsvError(() => parse('a,b\n1,2,"3"x', { header: true }), 2, 8, /Unexpected/);
  // A duplicate is found when its field ends, before a later bad character.
  assertCsvError(() => parse('a,a,"b"x', { header: true }), 1, 3, /Duplicate/);
  // A duplicate before an unclosed quote.
  assertCsvError(() => parse('a,a,"b', { header: true }), 1, 3, /Duplicate/);
  // A bad character before a later duplicate.
  assertCsvError(() => parse('"a"x,a', { header: true }), 1, 4, /Unexpected/);
});

test('CsvError is an Error subclass', () => {
  const err = new CsvError('boom', 2, 3);
  assert.ok(err instanceof Error);
  assert.equal(err.name, 'CsvError');
  assert.equal(err.line, 2);
  assert.equal(err.column, 3);
});

