'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { parse, createParser, CsvError } = require('../src/csv');

// Runs the input through a streaming parser split at the given offsets.
function streamParse(text, splits, options) {
  const parser = createParser(options);
  const records = [];
  let prev = 0;
  for (const at of [...splits, text.length]) {
    records.push(...parser.write(text.slice(prev, at)));
    prev = at;
  }
  records.push(...parser.end());
  return records;
}

function outcome(fn) {
  try {
    return { records: fn() };
  } catch (err) {
    assert.ok(err instanceof CsvError, `unexpected ${err && err.stack}`);
    return { error: { line: err.line, column: err.column, message: err.message } };
  }
}

const SAMPLES = [
  '',
  '﻿',
  '﻿a,b\r\nc,d\r\n',
  'a,"b\r\nc",d\re\n\n',
  '"a""b","""",""\r\n\r\n',
  '\r\n\r\r\n\n',
  'x,"y"z',
  'a,b\n"1\r\n2"\n3,"4\r',
  '"never closed\r\n',
  'h1,h2\r\n1,2\r\n3\r\n',
  'h,h\n',
  'h1,h2\n"a""","b"\r\n\n',
  ' a , "b" ,c\r\n',
];

const OPTION_SETS = [{}, { header: true }, { skipEmptyLines: true }, { header: true, skipEmptyLines: true }, { delimiter: ';' }];

test('every split into two or three chunks matches parse', () => {
  for (const options of OPTION_SETS) {
    for (const text of SAMPLES) {
      const expected = outcome(() => parse(text, options));
      for (let a = 0; a <= text.length; a++) {
        for (let b = a; b <= text.length; b++) {
          const actual = outcome(() => streamParse(text, [a, b], options));
          assert.deepEqual(actual, expected, `${JSON.stringify(text)} split at ${a},${b} with ${JSON.stringify(options)}`);
        }
      }
    }
  }
});

test('one code unit per chunk matches parse', () => {
  for (const options of OPTION_SETS) {
    for (const text of SAMPLES) {
      const splits = Array.from({ length: text.length }, (_, i) => i);
      assert.deepEqual(outcome(() => streamParse(text, splits, options)), outcome(() => parse(text, options)));
    }
  }
});

test('write returns records as their line breaks arrive', () => {
  const parser = createParser();
  assert.deepEqual(parser.write('a,b'), []);
  assert.deepEqual(parser.write(',c\nd'), [['a', 'b', 'c']]);
  assert.deepEqual(parser.write('\ne\nf'), [['d'], ['e']]);
  assert.deepEqual(parser.write(''), []);
  assert.deepEqual(parser.end(), [['f']]);
});

test('a CR at the end of a chunk ends the record; a following LF belongs to it', () => {
  const parser = createParser();
  assert.deepEqual(parser.write('a\r'), [['a']]);
  assert.deepEqual(parser.write('\nb\r'), [['b']]);
  assert.deepEqual(parser.write('\r'), [['']]);
  assert.deepEqual(parser.write('\n'), []);
  assert.deepEqual(parser.end(), []);
});

test('quoted fields and escaped quotes split across chunks', () => {
  const parser = createParser();
  assert.deepEqual(parser.write('"a,'), []);
  assert.deepEqual(parser.write('\r'), []);
  assert.deepEqual(parser.write('\nb"'), []);
  assert.deepEqual(parser.write('"c"'), []);
  assert.deepEqual(parser.write(',d\n'), [['a,\r\nb"c', 'd']]);
  assert.deepEqual(parser.end(), []);
});

test('byte order mark split from the rest of the input', () => {
  const parser = createParser();
  assert.deepEqual(parser.write(''), []);
  assert.deepEqual(parser.write('﻿'), []);
  assert.deepEqual(parser.write('﻿a\n'), [['﻿a']]);
  assert.deepEqual(parser.end(), []);
});

test('header mode streaming', () => {
  const parser = createParser({ header: true });
  assert.deepEqual(parser.write('a,b\n1,'), []);
  assert.deepEqual(parser.write('2\n3,4'), [{ a: '1', b: '2' }]);
  assert.deepEqual(parser.end(), [{ a: '3', b: '4' }]);
});

test('errors are thrown by the call that finds them', () => {
  const parser = createParser({ header: true });
  assert.deepEqual(parser.write('a,b\n1,2\n3'), [{ a: '1', b: '2' }]);
  assert.throws(
    () => parser.write('\n'),
    (err) => err instanceof CsvError && err.line === 3 && err.column === 1
  );

  const unclosed = createParser();
  assert.deepEqual(unclosed.write('x\n"abc\n'), [['x']]);
  assert.throws(
    () => unclosed.end(),
    (err) => err instanceof CsvError && err.line === 2 && err.column === 1
  );
});

test('the parser cannot be used after end()', () => {
  const parser = createParser();
  parser.write('a');
  parser.end();
  assert.throws(() => parser.write('b'), Error);
  assert.throws(() => parser.end(), Error);
});

test('the parser cannot be used after a method throws', () => {
  const parser = createParser();
  assert.throws(() => parser.write('"a"b'), CsvError);
  assert.throws(() => parser.write('c'), (err) => err instanceof Error && !(err instanceof CsvError));
  assert.throws(() => parser.end(), Error);

  const afterEnd = createParser();
  afterEnd.write('"a');
  assert.throws(() => afterEnd.end(), CsvError);
  assert.throws(() => afterEnd.end(), (err) => err instanceof Error && !(err instanceof CsvError));
  assert.throws(() => afterEnd.write(''), Error);
});

test('write only accepts strings', () => {
  for (const chunk of [undefined, null, 1, Buffer.from('a'), ['a']]) {
    const parser = createParser();
    assert.throws(() => parser.write(chunk), TypeError);
    assert.throws(() => parser.write('a'), Error);
  }
});

test('options are validated when the parser is created', () => {
  assert.throws(() => createParser({ delimiter: '"' }), TypeError);
  assert.throws(() => createParser({ delimiter: '\n' }), TypeError);
  assert.throws(() => createParser({ delimiter: 'ab' }), TypeError);
});

test('large input in tiny chunks takes linear time', { timeout: 20000 }, () => {
  const bigField = 'x'.repeat(200000);
  const text = `"${bigField.replace(/x{100}/g, '$&""')}"\r\n` + 'a,b,c\r\n'.repeat(30000);
  const parser = createParser();
  let count = 0;
  let first;
  for (let i = 0; i < text.length; i += 3) {
    const records = parser.write(text.slice(i, i + 3));
    if (!first && records.length) first = records[0];
    count += records.length;
  }
  count += parser.end().length;
  assert.equal(count, 30001);
  assert.equal(first[0].length, 202000);
});

