'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { parse, stringify } = require('../src/csv');

test('writes records joined by CRLF with a trailing CRLF', () => {
  assert.equal(
    stringify([
      ['a', 'b'],
      ['1', '2'],
    ]),
    'a,b\r\n1,2\r\n'
  );
});

test('no rows gives an empty string', () => {
  assert.equal(stringify([]), '');
  assert.equal(stringify([], { eol: '\n' }), '');
});

test('rows must be an array of arrays', () => {
  assert.throws(() => stringify('a'), TypeError);
  assert.throws(() => stringify(null), TypeError);
  assert.throws(() => stringify(['a']), TypeError);
  assert.throws(() => stringify([{ a: 1 }]), TypeError);
  assert.throws(() => stringify([null]), TypeError);
});

test('eol option', () => {
  assert.equal(stringify([['a'], ['b']], { eol: '\n' }), 'a\nb\n');
  assert.equal(stringify([['a'], ['b']], { eol: '\r\n' }), 'a\r\nb\r\n');
  for (const eol of ['\r', '', ';', '\n\r', null, 1]) {
    assert.throws(() => stringify([['a']], { eol }), TypeError, JSON.stringify(eol));
  }
});

test('value types', () => {
  assert.equal(stringify([['s', 1, -2.5, 0, true, false, null, undefined]]), 's,1,-2.5,0,true,false,,\r\n');
  assert.equal(stringify([[NaN, Infinity]]), 'NaN,Infinity\r\n');
  for (const value of [{}, [], 1n, Symbol('s'), () => {}, new Date(0), new String('a')]) {
    assert.throws(() => stringify([[value]]), TypeError);
  }
});

