'use strict';

// Randomized tests: parse is compared with an independent whole-string
// reference parser, the streaming parser with parse under random chunking,
// and stringify with parse for round trips.

const test = require('node:test');
const assert = require('node:assert/strict');
const { parse, createParser, stringify, CsvError } = require('../src/csv');

function mulberry32(seed) {
  return function random() {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = seed;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = mulberry32(0xc5f4180);
const pick = (items) => items[Math.floor(random() * items.length)];
const randomInt = (max) => Math.floor(random() * (max + 1));

// Straightforward reference implementation of the parse rules.
function referenceParse(text, { delimiter = ',', header = false, skipEmptyLines = false } = {}) {
  const s = text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
  const n = s.length;
  const isBreak = (ch) => ch === '\r' || ch === '\n';
  const breakLength = (at) => (s[at] === '\r' && s[at + 1] === '\n' ? 2 : 1);

  function fail(kind, offset) {
    let line = 1;
    let lineStart = 0;
    for (let k = 0; k < offset; k += 1) {
      if (isBreak(s[k])) {
        k += breakLength(k) - 1;
        line += 1;
        lineStart = k + 1;
      }
    }
    throw { kind, line, column: offset - lineStart + 1 };
  }

  const rows = [];
  let names = null;
  function addRecord(fields, offset) {
    if (!header) rows.push(fields);
    else if (names === null) names = fields;
    else if (fields.length !== names.length) fail('count', offset);
    else rows.push(Object.fromEntries(names.map((name, k) => [name, fields[k]])));
  }

  let i = 0;
  while (i < n) {
    if (isBreak(s[i])) {
      if (!skipEmptyLines) addRecord([''], i);
      i += breakLength(i);
      continue;
    }
    const recordStart = i;
    const fields = [];
    const seen = new Set();
    for (;;) {
      const fieldStart = i;
      let value = '';
      if (s[i] === '"') {
        let j = i + 1;
        for (;;) {
          if (j >= n) fail('unclosed', fieldStart);
          if (s[j] === '"' && s[j + 1] === '"') {
            value += '"';
            j += 2;
          } else if (s[j] === '"') {
            j += 1;
            break;
          } else {
            value += s[j];
            j += 1;
          }
        }
        if (j < n && s[j] !== delimiter && !isBreak(s[j])) fail('after-quote', j);
        i = j;
      } else {
        while (i < n && s[i] !== delimiter && !isBreak(s[i])) value += s[i++];
      }
      if (header && names === null) {
        if (seen.has(value)) fail('duplicate', fieldStart);
        seen.add(value);
      }
      fields.push(value);
      if (i < n && s[i] === delimiter) {
        i += 1;
        continue;
      }
      break;
    }
    addRecord(fields, recordStart);
    if (i < n) i += breakLength(i);
  }
  return rows;
}

const MESSAGE_BY_KIND = {
  unclosed: /^Unclosed quoted field/,
  'after-quote': /^Unexpected character/,
  duplicate: /^Duplicate header name/,
  count: /^Expected \d+ fields?/,
};

function result(fn) {
  try {
    return { records: fn() };
  } catch (err) {
    if (err instanceof CsvError) return { error: { line: err.line, column: err.column, message: err.message } };
    if (err && err.kind) return { error: { line: err.line, column: err.column, kind: err.kind } };
    throw err;
  }
}

function randomText(alphabet, maxLength) {
  let text = '';
  const length = randomInt(maxLength);
  for (let k = 0; k < length; k += 1) text += pick(alphabet);
  return text;
}

function randomSplits(length) {
  const splits = [];
  let at = 0;
  while (at < length) {
    at += 1 + randomInt(random() < 0.5 ? 1 : 6);
    if (at < length) splits.push(at);
    if (random() < 0.1) splits.push(at < length ? at : length); // empty chunks too
  }
  return splits;
}

function streamParse(text, splits, options) {
  const parser = createParser(options);
  const records = [];
  let prev = 0;
  for (const at of [...splits, text.length]) {
    for (const record of parser.write(text.slice(prev, at))) records.push(record);
    prev = Math.max(prev, at);
  }
  for (const record of parser.end()) records.push(record);
  return records;
}

const DELIMITERS = [',', ';', ' ', '\t', '﻿'];
const INPUT_ALPHABET = ['a', 'b', 'a', ' ', '"', '"', '"', ',', ',', ';', '\t', '\r', '\n', '\n', '\r\n', '﻿', '😀'];

function randomParseOptions() {
  const options = {};
  if (random() < 0.4) options.delimiter = pick(DELIMITERS);
  if (random() < 0.4) options.header = true;
  if (random() < 0.4) options.skipEmptyLines = true;
  return options;
}

test('parse agrees with the reference parser', () => {
  for (let iteration = 0; iteration < 30000; iteration += 1) {
    const text = randomText(INPUT_ALPHABET, 24);
    const options = randomParseOptions();
    const actual = result(() => parse(text, options));
    const expected = result(() => referenceParse(text, options));
    const context = `${JSON.stringify(text)} ${JSON.stringify(options)}`;
    if (expected.error) {
      assert.ok(actual.error, `expected an error for ${context}, got ${JSON.stringify(actual)}`);
      assert.equal(actual.error.line, expected.error.line, `line for ${context}`);
      assert.equal(actual.error.column, expected.error.column, `column for ${context}`);
      assert.match(actual.error.message, MESSAGE_BY_KIND[expected.error.kind], context);
    } else {
      assert.deepEqual(actual, expected, context);
    }
  }
});

test('streaming with random chunks agrees with parse', () => {
  for (let iteration = 0; iteration < 20000; iteration += 1) {
    const text = randomText(INPUT_ALPHABET, 30);
    const options = randomParseOptions();
    const expected = result(() => parse(text, options));
    const splits = randomSplits(text.length);
    const actual = result(() => streamParse(text, splits, options));
    assert.deepEqual(actual, expected, `${JSON.stringify(text)} ${JSON.stringify(options)} splits ${splits}`);
  }
});

test('parse(stringify(rows)) returns the rows', () => {
  const fieldAlphabet = ['a', 'b', ' ', '"', ',', ';', '|', '\t', '\r', '\n', '\r\n', '﻿', '😀'];
  for (let iteration = 0; iteration < 20000; iteration += 1) {
    const rows = [];
    const rowCount = 1 + randomInt(4);
    for (let r = 0; r < rowCount; r += 1) {
      const row = [];
      const fieldCount = 1 + randomInt(random() < 0.3 ? 0 : 4);
      for (let f = 0; f < fieldCount; f += 1) row.push(random() < 0.25 ? '' : randomText(fieldAlphabet, 5));
      rows.push(row);
    }
    const opts = {};
    if (random() < 0.6) opts.delimiter = pick([',', ';', '|', '\t', ' ', 'a', '﻿']);
    if (random() < 0.5) opts.eol = pick(['\n', '\r\n']);
    if (random() < 0.5) opts.skipEmptyLines = true;
    const text = stringify(rows, opts);
    const context = `${JSON.stringify(rows)} ${JSON.stringify(opts)} -> ${JSON.stringify(text)}`;
    assert.deepEqual(parse(text, opts), rows, context);
    assert.deepEqual(streamParse(text, randomSplits(text.length), opts), rows, context);
  }
});

