      if (!skipEmptyLines) addRecord([''], i);
      i += breakLength(i);
      continue;
    }
    const recordStart = i;
    const fields = [];
    const seen = new Set();
    for (;;) {
      const fieldStart = i;
      let value = '';
      if (s[i] === '"') {
        let j = i + 1;
        for (;;) {
          if (j >= n) fail('unclosed', fieldStart);
          if (s[j] === '"' && s[j + 1] === '"') {
            value += '"';
            j += 2;
          } else if (s[j] === '"') {
            j += 1;
            break;
          } else {
            value += s[j];
            j += 1;
          }
        }
        if (j < n && s[j] !== delimiter && !isBreak(s[j])) fail('after-quote', j);
